{
  "concepts": {
    "concepts": [
      {
        "term": "resource",
        "definition": "Single canonical item (skill, rule, MCP, hook, agent, ...)"
      },
      {
        "term": "plugin",
        "definition": "Named bundle of resources you apply to projects"
      },
      {
        "term": "profile",
        "definition": "Plugin tagged profile; apply globally with profile use"
      },
      {
        "term": "account",
        "definition": "HarnessTap Cloud login identity stored locally"
      },
      {
        "term": "environment",
        "definition": "Named how-values (vars, secrets, model config)"
      },
      {
        "term": "harness",
        "definition": "Target CLI (claude-code, codex, cursor, ...)"
      }
    ],
    "harness_roles": [
      {
        "term": "registered",
        "definition": "Harnesses HarnessTap writes to (harness set --harnesses)"
      },
      {
        "term": "default",
        "definition": "First registered harness: mirror source and scans when none is named"
      }
    ],
    "commands": [
      {
        "command": "plugin apply <plugin>",
        "purpose": "Materialize plugins onto a project"
      },
      {
        "command": "profile use <profile>",
        "purpose": "Apply a profile plugin globally to home harness files"
      },
      {
        "command": "migrate export <archive>",
        "purpose": "Share your full local workspace with another machine"
      },
      {
        "command": "mirror .",
        "purpose": "Sync registered harnesses from the first registered one on disk"
      },
      {
        "command": "plugin list --search foundation --remote-only",
        "purpose": "Browse public catalog plugins"
      },
      {
        "command": "plugin pull org/catalog/engineering-foundation",
        "purpose": "Cache a catalog plugin locally"
      },
      {
        "command": "plugin edit <plugin> --add <item> --type skill",
        "purpose": "Add a local resource to a plugin"
      }
    ],
    "environment_cascade": "home env ◂ plugin default env (last wins on apply)"
  },
